const canvas = document.getElementById('oscilloscope-canvas');
        const ctx = canvas.getContext('2d');
        const noteVal = document.getElementById('note-val');
        const hzVal = document.getElementById('hz-val');
        const centsText = document.getElementById('cents-text');
        const tunerNeedle = document.getElementById('tuner-needle');
        const statusText = document.getElementById('status-text');
        const liveIndicator = document.getElementById('live-indicator');
        const micStatus = document.getElementById('mic-status');
        const sampleRateDisplay = document.getElementById('sample-rate');
        const pauseBtn = document.getElementById('pause-btn');
        let audioContext = null;
        let analyser = null;
        let microphone = null;
        let isRunning = false;
        let isPaused = false;
        let animationId = null;
        let bufferLength;
        let dataArray;
        const noteStrings = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];
        function log(msg, type = 'default') {
            const term = document.getElementById('terminal');
            const content = document.getElementById('terminal-content');
            const line = document.createElement('div');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            const colorClass = type === 'success' ? 'text-violet-400' : (type === 'error' ? 'text-red-500' : 'text-slate-400');
            line.innerHTML = `<span class="opacity-30">[${time}]</span> <span class="${colorClass}">${msg}</span>`;
            content.appendChild(line);
            term.scrollTop = term.scrollHeight;
        }
        async function startAudio() {
            if (audioContext) return; // Prevent double start
            try {
                log("Requesting microphone access...");
                audioContext = new (window.AudioContext || window.webkitAudioContext)();
                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                microphone = audioContext.createMediaStreamSource(stream);
                analyser = audioContext.createAnalyser();
                analyser.fftSize = 2048;
                bufferLength = analyser.fftSize;
                dataArray = new Float32Array(bufferLength);
                microphone.connect(analyser);
                log("Audio Context initialized. Stream active.", "success");
                micStatus.innerText = "ACTIVE";
                micStatus.className = "text-violet-500 font-bold uppercase";
                sampleRateDisplay.innerText = `${(audioContext.sampleRate / 1000).toFixed(1)}kHz`;
                statusText.style.display = 'none';
                liveIndicator.style.display = 'block';
                pauseBtn.disabled = false;
                isRunning = true;
                updatePitch();
            } catch (err) {
                console.error(err);
                log("PERMISSION ERROR: Microphone access denied.", "error");
            }
        }
        // Standard Autocorrelation Algo
        function autoCorrelate(buf, sampleRate) {
            let SIZE = buf.length;
            let MAX_SAMPLES = Math.floor(SIZE / 2);
            let best_offset = -1;
            let best_correlation = 0;
            let rms = 0;
            let foundGoodCorrelation = false;
            let correlations = new Array(MAX_SAMPLES);
            for (let i = 0; i < SIZE; i++) {
                let val = buf[i];
                rms += val * val;
            }
            rms = Math.sqrt(rms / SIZE);
            // Noise gate
            if (rms < 0.01) return -1;
            let lastCorrelation = 1;
            for (let offset = 0; offset < MAX_SAMPLES; offset++) {
                let correlation = 0;
                for (let i = 0; i < MAX_SAMPLES; i++) {
                    correlation += Math.abs((buf[i]) - (buf[i + offset]));
                }
                correlation = 1 - (correlation / MAX_SAMPLES);
                correlations[offset] = correlation;
                if ((correlation > 0.9) && (correlation > lastCorrelation)) {
                    foundGoodCorrelation = true;
                    if (correlation > best_correlation) {
                        best_correlation = correlation;
                        best_offset = offset;
                    }
                } else if (foundGoodCorrelation) {
                    // Gaussian interpolation
                    let shift = (correlations[best_offset + 1] - correlations[best_offset - 1]) / 8;
                    return sampleRate / (best_offset + shift);
                }
                lastCorrelation = correlation;
            }
            if (best_correlation > 0.01) {
                return sampleRate / best_offset;
            }
            return -1;
        }
        function noteFromPitch(frequency) {
            const noteNum = 12 * (Math.log(frequency / 440) / Math.log(2));
            return Math.round(noteNum) + 69;
        }
        function frequencyFromNoteNumber(note) {
            return 440 * Math.pow(2, (note - 69) / 12);
        }
        function centsOffFromPitch(frequency, note) {
            return Math.floor(1200 * Math.log(frequency / frequencyFromNoteNumber(note)) / Math.log(2));
        }
        function updatePitch() {
            if (!isRunning) return;
            if (isPaused) {
                animationId = requestAnimationFrame(updatePitch);
                return;
            }
            analyser.getFloatTimeDomainData(dataArray);
            // Draw Oscilloscope
            drawOscilloscope();
            // Calculate Pitch
            const pitch = autoCorrelate(dataArray, audioContext.sampleRate);
            if (pitch !== -1 && pitch > 80 && pitch < 1200) { // Human range filter
                const noteNum = noteFromPitch(pitch);
                const noteName = noteStrings[noteNum % 12];
                // noteNum 69 is A4. Octave = floor((noteNum/12)-1)
                const octave = Math.floor(noteNum / 12) - 1;
                const detune = centsOffFromPitch(pitch, noteNum);
                noteVal.innerText = `${noteName}${octave}`;
                hzVal.innerText = `${pitch.toFixed(1)} Hz`;
                // Update Tuner Needle
                // Map -50 to 50 cents to 0% to 100% left position (50% is center)
                // Actually visual range: 10% to 90% screen width
                // needle 0 cents = 50% left
                let needlePos = 50 + (detune / 50) * 40; // Scale factor
                needlePos = Math.max(10, Math.min(90, needlePos)); // Clamp
                tunerNeedle.style.left = `${needlePos}%`;
                if (Math.abs(detune) < 5) {
                    tunerNeedle.style.backgroundColor = "#4ade80"; // Green
                    centsText.innerText = "PERFECT PITCH";
                    centsText.style.color = "#4ade80";
                } else if (detune < 0) {
                    tunerNeedle.style.backgroundColor = "#fbbf24"; // Yellow
                    centsText.innerText = `FLAT (${detune}c)`;
                    centsText.style.color = "#fbbf24";
                } else {
                    tunerNeedle.style.backgroundColor = "#ef4444"; // Red
                    centsText.innerText = `SHARP (+${detune}c)`;
                    centsText.style.color = "#ef4444";
                }
            } else {
                // No sound / Unclear
                // Keep last values or dim them?
                // noteVal.style.opacity = 0.5;
            }
            animationId = requestAnimationFrame(updatePitch);
        }
        function drawOscilloscope() {
            // Resize logic
            if (canvas.width !== canvas.clientWidth) {
                canvas.width = canvas.clientWidth;
                canvas.height = canvas.clientHeight;
            }
            ctx.fillStyle = '#020617';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            ctx.lineWidth = 2;
            ctx.strokeStyle = '#8b5cf6';
            ctx.beginPath();
            const sliceWidth = canvas.width * 1.0 / bufferLength;
            let x = 0;
            for (let i = 0; i < bufferLength; i++) {
                const v = dataArray[i] * 5.0; // Gain
                const y = (canvas.height / 2) + (v * canvas.height / 2);
                if (i === 0) {
                    ctx.moveTo(x, y);
                } else {
                    ctx.lineTo(x, y);
                }
                x += sliceWidth;
            }
            ctx.lineTo(canvas.width, canvas.height / 2);
            ctx.stroke();
        }
        window.toggleAnalyzer = function () {
            isPaused = !isPaused;
            const btnText = document.getElementById('pause-btn-text');
            if (isPaused) {
                btnText.innerText = "Resume Analysis";
                log("Analysis paused.");
            } else {
                btnText.innerText = "Pause Analysis";
                log("Analysis resumed.");
            }
        };

        log("Vocal Pitch Monitor Node initialized.");
